-- Complete item-based mount and battle-pet catalog from the Legion 7.3.5.26972 client.
-- Source: client DB2 CSV for Mount, MountXDisplay, BattlePetSpecies,
-- Creature, Item, ItemEffect and ItemSparse. Each entry has an existing
-- item, a learn-spell effect, a collection record and a preview model.
-- The item-ID release bands price newer collectibles above older ones.
-- Generated by tools/research/Generate-LegionCollectibleShop.ps1.

DROP TEMPORARY TABLE IF EXISTS `_battlepay_collectibles_317`;
CREATE TEMPORARY TABLE `_battlepay_collectibles_317` (
  `ProductID` INT UNSIGNED NOT NULL PRIMARY KEY,
  `GroupID` INT UNSIGNED NOT NULL,
  `ItemID` INT UNSIGNED NOT NULL UNIQUE,
  `Price` INT UNSIGNED NOT NULL,
  `Ordering` INT UNSIGNED NOT NULL,
  `ModelID` INT UNSIGNED NOT NULL,
  `Name` VARCHAR(255) NOT NULL
) ENGINE=MEMORY;

START TRANSACTION;








UPDATE `battlepay_product` p JOIN `_battlepay_collectibles_317` c ON c.`ProductID` = p.`ProductID`
SET p.`NormalPriceFixedPoint` = c.`Price`, p.`CurrentPriceFixedPoint` = c.`Price`
WHERE c.`ProductID` < 154;
UPDATE `battlepay_shop_entry` s JOIN `_battlepay_collectibles_317` c ON c.`ProductID` = s.`ProductID`
SET s.`Ordering` = c.`Ordering` WHERE c.`ProductID` < 154;

SELECT c.`ProductID`,c.`ModelID`,IF(c.`GroupID`=2,4,6),0,c.`Name`,IF(c.`GroupID`=2,'Mount','Battle pet'),
  'Use this item to add the collectible to your collection.','' FROM `_battlepay_collectibles_317` c WHERE c.`ProductID` >= 154
ON DUPLICATE KEY UPDATE `CreatureDisplayInfoID`=VALUES(`CreatureDisplayInfoID`),`FileDataID`=VALUES(`FileDataID`),
  `Flags`=VALUES(`Flags`),`Name1`=VALUES(`Name1`),`Name2`=VALUES(`Name2`),`Name3`=VALUES(`Name3`),`Name4`=VALUES(`Name4`);
DELETE v FROM `battlepay_display_info_visuals` v JOIN `_battlepay_collectibles_317` c ON c.`ProductID`=v.`DisplayInfoId` WHERE c.`ProductID` >= 154;
SELECT c.`ProductID`,c.`ModelID`,IF(c.`GroupID`=2,4,6),c.`Name` FROM `_battlepay_collectibles_317` c WHERE c.`ProductID` >= 154;

SELECT c.`ProductID`,c.`Price`,c.`Price`,0,0,0,c.`ProductID`,'',0,3 FROM `_battlepay_collectibles_317` c WHERE c.`ProductID` >= 154
ON DUPLICATE KEY UPDATE `NormalPriceFixedPoint`=VALUES(`NormalPriceFixedPoint`),`CurrentPriceFixedPoint`=VALUES(`CurrentPriceFixedPoint`),
  `DisplayInfoID`=VALUES(`DisplayInfoID`);
SELECT c.`ProductID`,c.`ProductID`,c.`ItemID`,1,0,0 FROM `_battlepay_collectibles_317` c WHERE c.`ProductID` >= 154
ON DUPLICATE KEY UPDATE `ItemID`=VALUES(`ItemID`),`Quantity`=VALUES(`Quantity`);
SELECT c.`ProductID`,c.`GroupID`,c.`ProductID`,c.`Ordering`,0,0,0 FROM `_battlepay_collectibles_317` c WHERE c.`ProductID` >= 154
ON DUPLICATE KEY UPDATE `GroupID`=VALUES(`GroupID`),`Ordering`=VALUES(`Ordering`);

COMMIT;
DROP TEMPORARY TABLE `_battlepay_collectibles_317`;
